afterAll(() => { detach(); cleanup(); });
it("works", async () => {
  const t = await createTenant("zzent", "enterprise");
  const s = await createTenant("zzst", "starter");
  const q = (ten: typeof t, q: string, extra: object = {}) => searchService.search(ten.actors.member, { orgId: ten.org.id, q, kinds: ["issue","comment","project"], limit: 25, cursor: null, ...extra } as never);
  const si = await issueService.createIssue(s.actors.member, issueInput(s.org.id, s.project.id, { title: "Release 2: hotfix" }));
  await commentService.createComment(s.actors.member, { orgId: s.org.id, issueId: si.id, body: "Release 2: hotfix c", parentId: null, mentionedUserIds: [] });
  expect((await q(s, "Release 2: hotfix")).total).toBe(1);
  const i = await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id, { title: "snake case 100" }));
  const c = await commentService.createComment(t.actors.member, { orgId: t.org.id, issueId: i.id, body: "flaky thing", parentId: null, mentionedUserIds: [] });
  expect((await q(t, "100%")).total).toBe(0);
  expect((await q(t, "snake_case")).total).toBe(0);
  expect((await q(t, "kind:comment flaky", { kinds: ["issue"] })).items[0]).toMatchObject({ kind: "comment", id: c.id });
  expect((await q(t, `in:comments project:${t.project.id} flaky`)).total).toBe(1);
  expect((await q(t, "flaky", { projectId: t.project.id })).total).toBe(1);
  await commentService.updateComment(t.actors.member, { orgId: t.org.id, commentId: c.id, body: "wobbly thing" });
  expect((await q(t, "wobbly", { projectId: t.project.id })).total).toBe(1);
  await searchRepo.deleteSearchDocument(t.org.id, "comment", c.id);
  await searchRepo.deleteSearchDocument(t.org.id, "project", t.project.id);
  const env = { orgId: t.org.id, actorId: null, occurredAt: new Date().toISOString() } as never;
  await emit("search.reindex_requested", { ...(env as object), subjectKind: "comment", subjectId: c.id } as never);
  await emit("search.reindex_requested", { ...(env as object), subjectKind: "project", subjectId: t.project.id } as never);
  expect((await q(t, "wobbly", { projectId: t.project.id })).total).toBe(1);
  expect((await q(t, "kind:project " + t.project.name)).total).toBeGreaterThan(0);
  await issueService.archiveIssue(t.actors.owner ?? t.actors.admin, t.org.id, i.id);
  await emit("search.reindex_requested", { ...(env as object), subjectKind: "issue", subjectId: i.id } as never);
  expect((await q(t, "snake case")).total).toBe(0);
});
